    /// <seealso href="http://purl.oclc.org/NET/ssnx/cf/cf-property#minus_one_times_surface_upwelling_shortwave_flux_in_air">http://purl.oclc.org/NET/ssnx/cf/cf-property#minus_one_times_surface_upwelling_shortwave_flux_in_air</seealso>
    let minus_one_times_surface_upwelling_shortwave_flux_in_air =
        Prefixed_Name(cfp, "minus_one_times_surface_upwelling_shortwave_flux_in_air") |> PrefixedName

