    /// <seealso href="http://purl.oclc.org/NET/ssnx/cf/cf-property#atmosphere_absorption_optical_thickness_due_to_black_carbon_ambient_aerosol">http://purl.oclc.org/NET/ssnx/cf/cf-property#atmosphere_absorption_optical_thickness_due_to_black_carbon_ambient_aerosol</seealso>
    let atmosphere_absorption_optical_thickness_due_to_black_carbon_ambient_aerosol =
        Prefixed_Name(cfp, "atmosphere_absorption_optical_thickness_due_to_black_carbon_ambient_aerosol") |> PrefixedName

