    let mass_concentration_of_phytoplankton_expressed_as_chlorophyll_in_sea_water =
        Prefixed_Name(cfp, "mass_concentration_of_phytoplankton_expressed_as_chlorophyll_in_sea_water") |> PrefixedName

    /// <summary>
    ///   <para>cfp:mass_concentration_of_picophytoplankton_expressed_as_chlorophyll_in_sea_water</para>
